package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Locality (canonical region) for pet owners, derived from the owner's city using a fixed
 * city-to-region table: {@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}.
 * Any city not in the table (or a null city) yields {@code UNKNOWN}. Derived purely from the
 * owner's own state, so it carries no stored data and is seed-independent. Used by the owner
 * mapper to expose {@code locality} on responses.
 */
public final class Locality {

    /** City -> canonical region. Fixed, pinned reference data. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private Locality() {
    }

    /**
     * The canonical region for the given city, or {@code UNKNOWN} when the city is not in the
     * fixed table.
     */
    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }
}
=== RequireCityCapacity ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Step of {@code POST /api/owners} that rejects a create when the owner's city already contains 50
 * or more owners, throwing {@link CityAtCapacityException} (handled as 409 Conflict). Cities are
 * compared case-insensitively with trimmed whitespace. Runs after {@link RequireOwnerFields} has
 * published the validated body and before {@link BuildOwner}/{@link SaveOwner} persist the new
 * owner.
 */
public class RequireCityCapacity {

    /** Maximum number of owners permitted in a single city. */
    private static final int CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = normalize(request.getCity());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equals(normalize(existing.getCity()))) {
                count++;
            }
        }
        if (count >= CITY_CAPACITY) {
            throw new CityAtCapacityException(
                    "City " + request.getCity() + " already has the maximum of " + CITY_CAPACITY
                            + " owners");
        }
    }

    private static String normalize(String city) {
        return city == null ? "" : city.trim().toLowerCase();
    }
}
=== OwnerAddress ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Shared normalization for the owner postal address. The canonical stored and returned form is
 * trimmed, has internal whitespace collapsed to single spaces, is upper-cased and has common
 * street-type abbreviations expanded ({@code ST -> STREET}, {@code RD -> ROAD},
 * {@code AVE -> AVENUE}). Applied when an owner is created so the stored address, the required-field
 * check and every household comparison (duplicate detection and the shared household id) all use the
 * same form.
 */
final class OwnerAddress {

    /** Whole-token street-type abbreviations expanded to their full form. */
    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private OwnerAddress() {
    }

    /**
     * @return the normalized address (trimmed, whitespace-collapsed, upper-cased, abbreviations
     * expanded), or an empty string when {@code address} is {@code null} or blank after trimming.
     */
    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}
