package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import tools.jackson.databind.node.ObjectNode;

/** Temp: region-range validation of postcode. */
class PostcodeRegionTest extends AcceptanceBase {

	@Test
	void rejectsPostcodeOutOfRangeForCityRegion() throws Exception {
		ObjectNode o = ownerNode();
		o.put("city", "Sydney"); // NSW 2000-2099
		o.put("postcode", "3000"); // VIC range -> invalid for NSW
		createOwner(o).andExpect(status().isBadRequest());
	}

	@Test
	void storesPostcodeValidForCityRegion() throws Exception {
		ObjectNode o = knownOwner("Brisbane"); // QLD -> 4000
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.postcode").value("4000"))
			.andExpect(jsonPath("$.locality").value("QLD"));
	}

	@Test
	void acceptsAnyFourDigitPostcodeForUnknownRegion() throws Exception {
		ObjectNode o = ownerNode(); // random city -> UNKNOWN
		o.put("postcode", "9999");
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.postcode").value("9999"));
	}
}
EOF
./mvnw -o test -Dtest=PostcodeRegionTest 2>&1 | grep -E "Tests run:|BUILD"
